  "查看发现": "Voir la découverte",
  "上次提交结果尚未确认；先重试原要求，当前草稿会保留。": "L'envoi précédent n'est pas confirmé. Réessayez d'abord sa demande d'origine ; votre brouillon actuel sera conservé.",
