  "已上传内容从中央读取；本机副本可能已清理。正文最长预览 100000 个字符，原件及完整内容可在中央查看。": "Le contenu envoyé est lu depuis le central ; la copie locale a pu être effacée. Les aperçus affichent jusqu'à 100 000 caractères. Consultez les originaux et le contenu complet dans le central.",
