  "媒体播放": "Lecture de médias",
  "锁屏与切换应用后，也可以留下播放线索。": "Des indices de lecture peuvent persister même écran verrouillé ou en changeant d'application.",
  "查看分布": "Voir la répartition",
  "重试": "Réessayer",
  "正在读取媒体记录…": "Chargement des enregistrements médias…",
  "这段时间还没有媒体观察记录": "Aucune observation de média sur cette période",
  "在 Android 客户端开启媒体采集并授权，记录同步后会出现在这里。没有记录不代表没有播放。": "Activez et autorisez la collecte des médias sur le client Android. Les enregistrements apparaissent après la synchronisation. L'absence d'enregistrements ne signifie pas qu'il n'y a eu aucune lecture.",
  "媒体播放采样时长": "Durée de lecture échantillonnée",
  "次状态观察": "observations d'état",
  "其中锁屏播放": "Dont lecture écran verrouillé",
