  "确认恢复部署配置": "Confirmer la restauration des paramètres de déploiement",
  "记录已同步到你的中央。": "Note rapide synchronisée avec votre nœud central.",
  "本机存储不可用或已满；草稿目前只在此窗口，请先复制保存。": "Le stockage local est indisponible ou plein. Le brouillon n'existe que dans cette fenêtre ; copiez-le d'abord.",
  "Mote 记录": "Note rapide Mote",
  "已保存到本机待同步队列，联网后会继续同步。": "Enregistrée dans la file d'attente locale. La synchronisation reprendra une fois connecté.",
  "移除这条本机待同步副本？若中央已收到但确认丢失，需要在下方历史记录中另行删除。": "Supprimer cette copie locale en attente de synchronisation ? Si le nœud l'a reçue mais que la confirmation s'est perdue, supprimez l'enregistrement archivé séparément ci-dessous.",
  "想到什么，就记下来。": "Notez les choses au fur et à mesure.",
  "心情、杂事、一个还没成形的想法，都可以成为上下文。": "Humeurs, petites tâches et idées encore floues peuvent tous devenir du contexte.",
  "此刻想留下什么？": "Que souhaitez-vous garder en ce moment ?",
  "记下此刻的想法…": "Notez vos pensées…",
  "草稿已保存在本机 ·": "Brouillon enregistré localement ·",
  "字": "caractères",
  "保存并同步": "Enregistrer et synchroniser",
  "草稿和待同步内容保存在此应用的本机存储中，清除应用数据会移除它们。打开记录时自动续传；按中央地址分别保存。": "Les brouillons et les notes en attente sont stockés localement dans cette application, par URL de nœud central. Effacer les données de l'application les supprime. La synchronisation reprend à l'ouverture des notes rapides.",
  "待同步 ·": "En attente de synchronisation ·",
