  "· 本机草稿仍可继续保存。": "· Les brouillons locaux peuvent toujours être enregistrés.",
  "给今天留一小段文字": "Laissez quelques mots pour aujourd'hui",
  "保存后，原文会出现在这里，也可作为问答的证据。": "Le texte enregistré apparaît ici et peut servir de preuve dans les réponses.",
