  "由中央定时同步你选定的日历，只申请读取权限。取消连接会移除本机授权，历史资料仍保留。": "Le nœud central synchronise périodiquement les calendriers sélectionnés avec un accès en lecture seule. La déconnexion supprime l'autorisation locale tout en conservant l'historique.",
