  "命名环境使用带 --profile 的启动命令；不会注册可能丢失环境参数的系统登录项。": "Lancez les environnements nommés avec --profile. Aucun élément de connexion système susceptible de perdre les arguments d'environnement n'est enregistré.",
  "应用启动后保持停止状态，需手动开始采集；已有记录按上传策略处理。": "La collecte reste arrêtée au lancement jusqu'à ce que vous la démarriez manuellement. Les enregistrements existants suivent la politique d'envoi.",
