  "操作尚未领取": "Action pas encore revendiquée",
  "缺少日历保存回执": "Reçu d'enregistrement du calendrier manquant",
  "日程证据校验失败": "Échec de la validation des preuves du calendrier",
  "日程关联校验失败": "Échec de la validation de l'association au calendrier",
  "日程分析未完成，可能是模型不可用、证据更新或结果未通过校验。可重试失败批次。": "Analyse d'événement incomplète : modèle indisponible, preuves modifiées ou validation échouée. Réessayez les lots en échec.",
  "请在中央网页的行动设置中授权此设备查看和确认日程建议": "Autorisez cet appareil dans les paramètres Action du web central pour voir et confirmer les suggestions",
