  "更换服务地址或类型时，请重新填写或清除密钥": "Lors du changement d'URL ou de type de service, remplacez ou effacez la clé",
  "归档方案不能设置处理步骤": "Les plans d'archivage seul ne peuvent pas définir d'étapes de traitement",
  "所选处理插件不可用": "Le plugin de traitement sélectionné est indisponible",
  "方案需要选择内容提取插件": "Sélectionnez un plugin d'extraction de contenu pour ce plan",
