  "用生成的图文样张比较小字、渐变和细线。只在内存处理，不读取或上传屏幕。": "Comparez petits textes, dégradés et lignes fines à l'aide d'un échantillon généré. Traité en mémoire ; aucune lecture ni envoi de l'écran.",
