  "下载完成，可以安装": "Téléchargé ; prêt à installer",
  "正在重新校验安装文件，可取消": "Revérification du fichier d'installation ; annulation possible",
  "正在提交安装文件给 Android": "Envoi du fichier d'installation à Android",
  "等待系统安装确认；未弹出时查看通知，或取消待确认安装后重试": "En attente de la confirmation du système. Consultez les notifications si aucune invite n'apparaît, ou annulez l'installation en attente et réessayez.",
  "系统已完成更新；已有应用数据保留": "Mise à jour du système terminée ; données de l'application conservées",
  "请在系统允许此应用安装更新，返回后再次点击安装": "Autorisez cette application à installer des mises à jour dans les paramètres système, puis revenez et touchez Installer",
  "APK 签名与当前应用不兼容或无效，已阻止更新；不会卸载旧应用": "Signature de l'APK incompatible ou invalide. Mise à jour bloquée ; l'ancienne application ne sera pas désinstallée.",
