  "正在导出本机记录…": "Exportation des enregistrements locaux…",
  "设置正在变更，请稍后重试": "Les paramètres sont en cours de modification. Réessayez plus tard.",
  "正在校验备份…": "Validation de la sauvegarde…",
  "备份属于不同中央。先连接原节点": "La sauvegarde appartient à un autre nœud. Connectez d'abord le nœud d'origine.",
  "导入 {0} 条本机记录？": "Importer {0} enregistrements locaux ?",
  "记录已导入 · 手动同步": "Enregistrements importés · Synchronisation manuelle",
