  "扫描中央生成的连接二维码\n仅用于本次扫码；画面不保存、不上传。返回可用粘贴或 JSON 文件连接。": "Scannez le QR code de connexion généré par votre nœud central\nLa caméra n'est utilisée que pour le scan ; les images ne sont ni enregistrées ni envoyées. Vous pouvez aussi coller une invitation ou importer un JSON.",
