  "请先保存修改后的同步范围。": "Enregistrez d'abord la portée de synchronisation modifiée.",
  "断开会停止读取并暂停这些来源，保留已归档资料。飞书端授权及 CLI 凭据仍保留，可在飞书中单独撤销。": "La déconnexion arrête les lectures et suspend ces sources tout en conservant le contenu archivé. L'autorisation Feishu et les identifiants CLI restent ; révoquez l'accès séparément dans Feishu.",
