  "尚未配置飞书应用。请创建应用或填写已有应用凭据。": "Aucune application Feishu n'est configurée. Créez-en une ou saisissez les identifiants d'une application existante.",
  "尚未连接飞书账号，请完成只读授权。": "Aucun compte Feishu n'est connecté. Terminez l'autorisation en lecture seule.",
