  "操作超时。请检查服务端网络，或重新发起授权。": "L'opération a dépassé le délai. Vérifiez le réseau du serveur ou relancez l'autorisation.",
  "飞书 CLI 操作未完成。请检查网络、应用权限及服务账号的系统钥匙串访问，再重试。": "L'opération Feishu CLI a échoué. Vérifiez le réseau, les autorisations de l'application et l'accès au trousseau système du compte de service, puis réessayez.",
