  "这是用户主动纠正的版本，原始说明已保留。": "Cette version a été explicitement corrigée par l'utilisateur. La déclaration originale est conservée.",
  "已通过独立模型审核和引用校验。": "Révision par un modèle indépendant et vérifications des citations réussies.",
  "模型未补充不确定性；可查看下方证据核对。": "Le modèle n'a fourni aucun détail d'incertitude. Vous pouvez examiner les preuves ci-dessous.",
  "纠正记忆": "Corriger la mémoire",
  "纠正后的内容": "Contenu corrigé",
  "记忆以文本保存，可按需查看概览、内容与边界、原始证据。通过自动审核和证据校验后直接生效，你可以随时纠正或删除。历史资料提取按窗口处理已圈定的积压，每轮窗口上限控制成本。": "Les mémoires sont enregistrées sous forme de texte. Consultez les résumés, les contenus, les limites et les preuves originales selon vos besoins. Elles prennent effet après une révision automatique et une validation des preuves, et vous pouvez les corriger ou les supprimer à tout moment. L'extraction historique traite un arriéré délimité par fenêtres ; la limite de fenêtre par cycle contrôle le coût.",
  "尚未生效": "Pas encore active",
  "未补充判断边界；可查看下方原始说明。": "Aucune limite n'a été fournie. Vous pouvez consulter la déclaration originale ci-dessous.",
  "这是你的主动纠正；原始说明和旧版本均已保留。": "Ceci est votre correction explicite. La déclaration originale et les versions antérieures sont conservées.",
  "已过期": "Expiré",
  "本次提取方案": "Recettes de cette extraction",
