  "默认提取方式": "Extraction par défaut",
  "选择仅用于本次提取。各方案会等待自己需要的资料，已完成的结果可立即查看；不选择时使用默认提取方式。": "Ces choix s'appliquent à cette extraction. Chaque recette attend les documents dont elle a besoin, et les résultats terminés sont disponibles immédiatement. Ne rien cocher pour utiliser l'extraction par défaut.",
