  "取消未完成方案": "Annuler les recettes non terminées",
  "重新检查未完成方案": "Revérifier les recettes non terminées",
  "重试会复用仍有效的提取结果；结果不可用或资料、设置变化时，可能重新提取。历史用量会保留。": "Les nouvelles tentatives réutilisent les résultats d'extraction encore valides. Si les résultats sont indisponibles ou si les documents ou les paramètres ont changé, l'extraction peut être relancée. L'utilisation passée est conservée.",
  "所需资料仍在处理中，就绪后会自动继续。": "Le document requis est encore en cours de traitement. Cette recette continuera automatiquement une fois prêt.",
  "所需资料处理失败，请查看来源并修复后重新检查。": "Le traitement du document requis a échoué. Inspectez la source, corrigez le traitement et revérifiez.",
  "所需资料不可用，请查看来源与处理状态。": "Le document requis est indisponible. Inspectez sa source et son état de traitement.",
