  "所选资料无效，请重新打开原始记录。": "L'enregistrement sélectionné est invalide. Rouvrez l'enregistrement original.",
  "问答读取原图尚未开启。请在中央感知设置中允许查询模型按需读取原图，再重新提问。": "L'accès aux images originales pour les requêtes est désactivé. Activez l'accès aux images à la demande pour le modèle de requête dans les paramètres de perception centrale, puis reposez la question.",
  "OCR 已取消": "OCR annulée",
  "中央文字识别已取消，截图已保留；当前没有正在处理的识别任务。": "L'OCR central a été annulée. La capture est conservée ; aucune tâche de reconnaissance n'est en cours.",
  "OCR 未启用": "OCR non activée",
  "中央文字识别未启用，截图已保留；当前不会自动识别文字。": "L'OCR central n'est pas activée. La capture est conservée ; le texte ne sera pas reconnu automatiquement.",
  "OCR 暂不可用": "OCR indisponible",
  "中央文字识别模型尚未安装，截图已保留。": "Le modèle d'OCR central n'est pas installé. La capture est conservée.",
  "中央文字识别被阻止，请检查中央感知配置与处理状态。截图已保留。": "L'OCR central est bloquée. Vérifiez la configuration de la perception centrale et l'état du traitement. La capture est conservée.",
  "截图已保存，文字识别任务正在排队或处理。": "Capture enregistrée. La reconnaissance de texte est en file d'attente ou en cours.",
  "文字识别已完成，下方显示这条记录保留的全文。": "La reconnaissance de texte est terminée. Le texte complet conservé est affiché ci-dessous.",
  "文字识别失败，截图已保留。": "La reconnaissance de texte a échoué. La capture est conservée.",
  "日期按当前浏览器时区显示。这里展示已同步到中央的记录；可刷新查看文字识别的最新状态与结果。": "Les dates utilisent le fuseau horaire actuel du navigateur. Ces enregistrements ont été synchronisés avec le nœud central ; actualisez pour voir le dernier état et les résultats de la reconnaissance de texte.",
  "当前处理尚未结束，请稍后再试。": "L'appel de traitement en cours n'est pas terminé. Veuillez réessayer plus tard.",
  "上次处理是否结束未知，重试可能重复执行。请确认后继续。": "On ignore si l'appel de traitement précédent est terminé. Réessayer peut le relancer. Confirmez pour continuer.",
  "当前调用尚在等待结束；此时不能重试。": "En attente de la fin de l'appel en cours. Une nouvelle tentative est indisponible pour le moment.",
  "本次处理已取消，不再保存后续结果；原件和已保存的成果保留。": "Cette exécution de traitement est annulée. Les résultats ultérieurs ne seront pas enregistrés ; les originaux et les résultats déjà enregistrés sont conservés.",
