  "处理队列已停用": "File de traitement désactivée",
  "处理队列已停用，请启用后继续。": "La file de traitement est désactivée. Activez-la pour continuer.",
  "使用所选语言模型合并自然发言轮次": "Utiliser le modèle de langue sélectionné pour fusionner les tours de parole naturels",
  "需要说话人分离插件": "Plugin de séparation des locuteurs requis",
  "每个方案拥有自己的参数。界面字段来自已加载的 Cordis 插件；密钥在下方服务中统一管理。本地多人录音保留未校正逐字记录；摘要与语义分析使用所选模型。": "Chaque plan possède ses propres paramètres. Les champs proviennent des plugins Cordis chargés ; gérez les clés dans Services ci-dessous. L'audio local à plusieurs locuteurs conserve les transcriptions brutes ; les résumés et l'analyse sémantique utilisent le modèle sélectionné.",
  "已就绪": "Prêt",
  "图片处理进度": "Progression du traitement des images",
  "中央图片方案": "Plan d'images central",
