  "图片默认使用中央图片方案，原件保存后自动处理。": "Les images suivent le plan d'images central et sont traitées automatiquement après l'enregistrement des originaux.",
  "跟随默认设置": "Suivre les paramètres par défaut",
  "仅保存原件": "Enregistrer les originaux uniquement",
  "正式接纳的截图、导入图片、同步图片和资料附件共享中央方案。原件先保存，各步骤独立完成。": "Les captures acceptées, les images importées, les images synchronisées et les pièces jointes des documents partagent le plan central. Les originaux sont d'abord enregistrés, puis chaque étape s'achève indépendamment.",
  "自动处理新图片": "Traiter automatiquement les nouvelles images",
  "文字识别服务": "Service OCR",
  "后台理解画面与来源上下文": "Comprendre les images et le contexte des sources en arrière-plan",
  "内容理解使用中央文件分析模型：{0}": "La compréhension du contenu utilise le modèle central d'analyse de fichiers : {0}",
  "查看记忆设置": "Voir les paramètres de mémoire",
  "服务、插件参数与来源覆盖在文件处理策略中维护。图片设置通过引用复用这些配置。": "Gérez les services, les paramètres des plugins et les remplacements par source dans les politiques de traitement des fichiers. Les paramètres d'image réutilisent ces configurations par référence.",
  "查看处理策略": "Voir les politiques de traitement",
  "允许图片发往已选择的远程 OCR 服务": "Autoriser l'envoi des images au service OCR distant sélectionné",
  "保存图片设置": "Enregistrer les paramètres d'image",
  "补处理已有图片": "Traiter les images existantes",
  "选择范围后一次安排，中央会持续分批执行。补齐会复用已有成果；重新计算会产生新版本。": "Sélectionnez une plage et planifiez-la une fois. Le nœud central poursuit par lots. Compléter les étapes manquantes réutilise les résultats existants ; recalculer crée de nouvelles versions.",
  "处理方式": "Mode de traitement",
