  "图片处理成果请使用 npm run backup 完整备份；JSON 导出不包含图片理解版本。": "Utilisez npm run backup pour une sauvegarde complète des résultats du traitement des images ; l'export JSON n'inclut pas les versions d'interprétation des images.",
  "原始采集记录": "Enregistrements de capture d'origine",
