  "部分内容": "Contenu partiel",
  "仍在整理": "Organisation en cours",
  "包括 Coding Agent 会话；可读内容不等待记忆整理。": "Inclut les sessions Coding Agent. Le contenu lisible n'attend pas le traitement de la mémoire.",
  "资料目录已变化，请返回第一页继续浏览。": "La bibliothèque a changé. Revenez à la première page pour continuer à parcourir.",
  "部分产物仍在处理，可先阅读已有内容。": "Certains résultats sont encore en traitement. Le contenu disponible peut déjà être lu.",
  "Coding Agent 会话": "Sessions Coding Agent",
  "处理插件实例已停用，请检查配置后重试。": "Cette instance de plugin de traitement a été désactivée. Vérifiez la configuration avant de réessayer.",
  "筛选": "Filtrer",
  "这些提取门槛与最大等待时间只控制历史资料的窗口处理。已授权且内容就绪的新资料直接进入自动记忆队列，按可用名额持续处理。": "Ces seuils d'extraction et cette attente maximale ne s'appliquent qu'aux fenêtres de traitement historique. Les enregistrements nouvellement autorisés au contenu prêt entrent directement dans la file de mémoire automatique et sont traités à mesure que la capacité se libère.",
  "持续整理新资料": "Traiter en continu les nouveaux enregistrements",
  "为新接收的来源资料选择记忆策略。多个策略可共用处理结果；保存设置不会重算历史资料，已有记忆仍保留。": "Choisissez les stratégies de mémoire pour les nouveaux enregistrements de sources. Les stratégies peuvent partager les résultats de traitement ; l'enregistrement ne retraite pas l'historique et les mémoires existantes sont conservées.",
  "我的表达或经历": "Mes expressions ou expériences",
  "第三方内容": "Contenu de tiers",
  "混合内容": "Contenu mixte",
  "归属未知": "Attribution inconnue",
  "你对这份资料的声明": "Votre déclaration pour cet enregistrement",
  "你对来源的声明": "Votre déclaration de source",
  "来源提供的上下文": "Contexte fourni par la source",
  "尚无归属声明": "Aucune déclaration d'attribution",
  "内容与我的关系": "Relation avec moi",
  "归属依据": "Base d'attribution",
  "来源声明": "Déclaration de source",
  "资料声明版本": "Version de déclaration de l'enregistrement",
  "来源内容归属（可选）": "Attribution de la source (facultatif)",
  "纠正内容归属（可选）": "Corriger l'attribution (facultatif)",
  "声明帮助模型区分你的表达、第三方内容和混合引用；归属未知也能查询和整理。": "Les déclarations aident le modèle à distinguer vos expressions, le contenu de tiers et les citations mixtes. Une attribution inconnue permet quand même la récupération et le traitement.",
  "来源声明应用于已有和新资料；单份资料的声明优先。": "Les déclarations de source s'appliquent aux enregistrements existants et nouveaux ; les déclarations par enregistrement prévalent.",
  "不声明": "Aucune déclaration",
  "跟随来源": "Suivre la source",
