  "原文": "Texte original",
  "自动记忆进度": "Progression de la mémoire automatique",
  "按本次新记录接收时选中的配方处理；进度按记录汇总。": "Utilise les recettes sélectionnées à la réception de ces nouveaux enregistrements ; la progression est agrégée par enregistrement.",
  "完成 {0} / {1} · 处理中 {2} · 等待内容或名额 {3}": "Terminées {0} / {1} · En traitement {2} · En attente de contenu ou de capacité {3}",
  "失败 {0} · 等待模型 {1} · 暂停 {2} · 已取消 {3} · 未启用 {4} · 输入已变更或不可用 {5}": "Échouées {0} · En attente du modèle {1} · En pause {2} · Annulées {3} · Désactivées {4} · Entrée modifiée ou indisponible {5}",
  "工作步骤名额：后台实际 {0}（配置 {1}），交互 {2}，合计 {3}。两条队列独立，不借用名额。": "Capacité des étapes de travail : arrière-plan effectif {0} (configuré {1}), interactif {2}, total {3}. Les files ont des capacités indépendantes.",
