  "规则 ID 与其他应用冲突，请为导入规则使用独立 ID": "Un ID de règle est en conflit avec une autre app. Utilisez des ID distincts pour les règles importées.",
  "规则配置与应用内容授权分开。修改只形成草稿，返回后保存生效；保存不会开始采集。": "La configuration des règles et l'autorisation de contenu de l'app sont distinctes. Les modifications forment un brouillon ; enregistrez au retour pour les appliquer. L'enregistrement ne démarre pas la capture.",
