  "高级：查看或编辑全部页面规则": "Avancé : voir ou modifier toutes les règles de page",
  "使用投屏模式（只截图，每次需授权）": "Utiliser le mode projection (captures uniquement ; consentement requis à chaque fois)",
  "默认无障碍采集支持页面字段与截图回退。选择投屏会同时改为只截图，锁屏/被杀后必须重新授权。Android 10 截图请选投屏模式。": "La capture d'accessibilité prend en charge les champs de page et le repli sur les captures. Choisir la projection sélectionne aussi « captures uniquement » ; le consentement doit être renouvelé après verrouillage ou arrêt. Utilisez la projection pour les captures sur Android 10.",
  "本周期累计页面 {0} · 截图 {1} · 应用活动 {2} · 媒体 {3} · 笔记 {4} · 已确认 {5}\n拦截 {6} · 失败 {7} · 重试结果 {8}": "Cette période : pages {0} · Captures {1} · Activité {2} · Médias {3} · Notes {4} · Confirmés {5}\nBloqués {6} · Échoués {7} · Résultats des réessais {8}",
  "本周期累计页面 {0}    截图 {1}    活动 {2}    媒体 {3}    记录 {4}\n本周期已同步 {5} 条": "Cette période : pages {0}    Captures {1}    Activité {2}    Médias {3}    Notes {4}\nSynchronisés cette période : {5}",
  "媒体采集可单独开启，在前台、后台和锁屏时观察播放器公开的状态、应用及曲目/章节信息；不录音、不控制播放。普通通知由单独的通知采集开关控制。使用本机页的开始/暂停控制采集。媒体沿用应用隐私规则、电量限制和同步策略；关闭元数据会同时暂停媒体。": "Observe indépendamment l'état public du lecteur, l'app et les informations de piste/chapitre au premier plan, en arrière-plan et sur l'écran de verrouillage. Aucun enregistrement audio ni contrôle de lecture. Les notifications ordinaires ont un interrupteur séparé. Utilisez Démarrer/Pause dans Appareil. Les politiques de confidentialité des apps, de batterie et de synchronisation s'appliquent ; désactiver les métadonnées met aussi les médias en pause.",
  "日常事件": "Événements quotidiens",
  "截图和页面采集默认组合": "Paramètres par défaut des captures d'écran et de pages",
  "截图和页面采集使用独立默认组合；来源覆盖优先。日常事件保留浏览和行动线索，区分计划与完成，并可在对话中按天回顾。": "Les captures d'écran et de pages utilisent des paramètres par défaut distincts ; les remplacements par source sont prioritaires. Les événements quotidiens conservent l'historique de navigation et d'actions, distinguent les plans des réalisations et peuvent être rappelés par jour dans la conversation.",
  "待回答": "En attente de votre réponse",
  "稍后处理": "Reporté",
