  "准备厂商账号与读取授权": "Préparer le compte du fournisseur et l'autorisation de lecture",
  "资料变化，待重新核对": "L'élément a changé ; à revérifier",
  "资料范围尚不完整或仍在整理。请核对已有正文；缺失部分不能作为已经读取的证据。": "La couverture des éléments est incomplète ou encore en traitement. Vérifiez le corps disponible ; les parties manquantes ne peuvent pas compter comme des preuves déjà lues.",
  "资料来源": "Source des éléments",
