  "附件与处理说明": "Pièces jointes et traitement",
  "文字识别与音频转写按中央处理设置进行；可在资料库核对各阶段状态。": "L'OCR et la transcription audio suivent les paramètres de traitement du nœud central. Examinez chaque étape dans la bibliothèque.",
  "资料已更新，本次结果失效": "La source a changé ; ce résultat n'est plus valide.",
  " · {0} 批输入已失效": " · {0} lots ont des entrées invalidées",
  " · {0} 项输入已失效": " · {0} entrées ne sont plus valides",
  "历史结果保留；请查看当前资料版本。失效输入不能直接重试。": "Les résultats historiques sont conservés. Consultez la version actuelle de la source ; une entrée invalidée ne peut pas être relancée directement.",
  "{0} 次用量不完整": "Exécutions avec utilisation incomplète : {0}",
  "{0} 次用量缺失或不完整 ·": "Utilisation manquante ou incomplète : {0} ·",
  "{0} 次费用未估算。缓存率按已上报缓存数据的输入 token 加权；未知部分不按零计算。": "Sans estimation de coût : {0}. Les taux de cache sont pondérés par les jetons d'entrée pour les données de cache rapportées. Les valeurs inconnues ne sont pas comptées comme zéro.",
  "符合筛选的 {0} 次运行，显示最近 {1} 次；所有统计覆盖全部符合条件的记录。": "Exécutions correspondantes : {0} ; affichage des {1} plus récentes. Toutes les statistiques couvrent l'ensemble des enregistrements correspondants.",
  "{0} 条证据": "Preuves : {0}",
  "当前授权资料不能提供所需语境，未完成范围已保留。": "Les éléments autorisés ne peuvent pas fournir le contexte requis. La couverture inachevée a été conservée.",
  "内部规划未完成，已保存的结果和未完成范围均保留。请查看失败原因后决定是否重试。": "La planification interne n'a pas abouti. Les résultats enregistrés et la couverture inachevée sont conservés. Examinez l'échec avant de décider de réessayer.",
  "内部规划执行失败，未自动重放未知错误。": "La planification interne a échoué. Les erreurs inconnues n'ont pas été relancées automatiquement.",
  "内部规划结果未通过校验，未完成范围已保留。": "Le plan interne n'a pas passé la validation. La couverture inachevée a été conservée.",
