  "内部规划失败，未完成范围已保留": "Échec de la planification interne ; la couverture inachevée est conservée",
  "本次整合的记忆或原始证据当前不可读，未完成窗口已保留。请检查来源与授权后重试。": "Les mémoires ou preuves d'origine sélectionnées sont actuellement illisibles. La fenêtre inachevée est conservée. Vérifiez les sources et les autorisations avant de réessayer.",
  "本次整合未读到记忆正文或原始证据，未完成窗口已保留，未记为成功。": "Cette intégration n'a reçu aucun corps de mémoire ni preuve d'origine. La fenêtre inachevée est conservée et n'a pas été marquée comme réussie.",
  "当前记忆引擎不支持这项原始证据，请更换支持的方案后重新发起。": "Le moteur de mémoire actuel ne prend pas en charge cette preuve d'origine. Sélectionnez une configuration compatible et recommencez.",
  "连接中央后查看资料整理、问答与记忆工作的进展。": "Connectez-vous au nœud central pour voir la progression du traitement des éléments, des questions et du travail de mémoire.",
