  "这是你的 Mote 吗？": "Est-ce bien votre Mote ?",
  "这台设备将可以访问你的全部资料和设置。\n新保存的记录将按当前发送设置同步到这里。": "Cet appareil aura accès à tous vos documents et réglages.\nLes nouvelles notes seront synchronisées ici selon vos réglages d’envoi actuels.",
  "将使用已有设备 ID 和当前采集设置，不会清空设置、队列或模型。首次连接会把尚未绑定的本机资料绑定到此节点；已绑定其他节点的待同步资料不能改投。": "L’identifiant de l’appareil et les réglages de capture sont conservés. Les réglages, files et modèles ne sont pas effacés. La première connexion associe les documents locaux non affectés à ce nœud. Les documents en attente déjà associés à un autre nœud ne peuvent pas être redirigés.",
