  "只展示主线签发的固定制品。安装不等于授权，也不等于切换 Memory 方案或开始扫描历史。": "Seuls les artefacts fixes signés par la ligne principale sont listés. L'installation n'autorise pas, ne change pas le plan Memory et ne scanne pas l'historique.",
  "当前没有可安装的官方制品。": "Aucun artefact officiel disponible à installer.",
  "预览并安装": "Prévisualiser et installer",
  "已移至「设置 → 运行与诊断」。": " Déplacé vers Réglages → Exécution et diagnostic.",
  "官方目录在「自动记忆与插件」。": "Le catalogue officiel se trouve sous Mémoire automatique et plugins.",
  "已安装，待配置": "Installé, configuration en attente",
  "已配置，待核验": "Configuré, vérification en attente",
  "可连接": "Prêt à connecter",
