  "这份草稿已失效，请回到原回答重新生成。": "Ce brouillon n'est plus à jour. Revenez à la réponse d'origine et générez-en un nouveau.",
  "草稿提交失败，请重试。": "Le brouillon n'a pas pu être envoyé. Réessayez.",
