  "消息仍需逐条确认；日历按已有授权执行。": "Chaque message doit être confirmé ; le calendrier utilise les autorisations existantes.",
  "创建行动建议": "Créer une proposition d’action",
  "当前连接或授权范围不支持这项行动。": "La connexion ou l’autorisation actuelle ne couvre pas cette action.",
  "正在读取文件状态…": "Lecture de l’état du fichier…",
  "文件状态": "État du fichier",
  "未提供位置": "Emplacement non fourni",
  "最后确认（来源观察）": "Dernière confirmation (observation de la source)",
  "位置状态": "État de l’emplacement",
  "原位置已不可见": "L’emplacement d’origine n’est plus visible",
  "未报告原位置缺失": "Aucune disparition de l’emplacement d’origine signalée",
  "原件能力": "Accès à l’original",
  "可打开原件": "L’original peut être ouvert",
  "正文提取": "Extraction du texte",
  "来源最近一次观察时间不代表设备当前在线。提取、语义理解、向量索引和原件打开分别确认。": "La dernière observation de la source ne signifie pas que l’appareil est actuellement en ligne. L’extraction, l’analyse sémantique, l’indexation vectorielle et l’accès à l’original sont confirmés séparément.",
  "快照原件未保留；已提取正文仍按当前覆盖和读取权限提供。": "L’original de l’instantané n’est pas conservé. Le texte extrait reste accessible selon la couverture actuelle et les autorisations de lecture.",
  "内容提取或生成摘要不代表已完成全文语义理解。": "L’extraction du contenu ou la génération d’un résumé ne garantit pas une analyse sémantique complète du fichier.",
  "向量索引尚未完整就绪；可用正文仍可通过文本检索查找。": "L’indexation vectorielle n’est pas entièrement prête. Le texte disponible reste accessible par recherche textuelle.",
  "问文件": "Interroger ce fichier",
  "请基于这份文件拟定可编辑的工作草稿，说明目标和资料范围，等我确认后开始。": "Prépare un brouillon de travail modifiable à partir de ce fichier. Précise l’objectif et le périmètre des documents, puis attends ma confirmation avant de commencer.",
  "用于事项": "Utiliser pour un dossier",
  "用于事项会先准备可编辑草稿，点击开始后才执行。": "Cette action prépare d’abord un brouillon modifiable. Le travail ne s’exécute qu’après un clic sur Démarrer.",
  "保存方式只提交当前选择，不更改其他来源设置。已有文件的实际能力以文件状态为准。": "L’enregistrement ne soumet que le mode de conservation sélectionné, sans modifier les autres réglages de la source. Consultez l’état de chaque fichier existant pour connaître ses capacités réelles.",
  "对话与上下文": "Conversations et contexte",
  "历史比例": "Ratio d’historique",
  "低水位": "Seuil bas",
  "上下文窗口": "Fenêtre de contexte",
