  "配置窗口": "Fenêtre configurée",
  "上下文设置": "Paramètres du contexte",
  "低水位比例": "Seuil bas",
  "低水位比例需要大于等于 0 且小于 1。": "Le seuil bas doit être supérieur ou égal à 0 et inférieur à 1.",
  "使用服务端标注的保守窗口": "Utiliser la fenêtre prudente indiquée par le serveur",
  "保存对话设置": "Enregistrer les paramètres de conversation",
