  "历史预算比例": "Part du budget d’historique",
  "历史预算比例需要在 0 到 1 之间。": "La part du budget d’historique doit être comprise entre 0 et 1.",
  "对话设置已保存。": "Paramètres de conversation enregistrés.",
  "已接收": "Reçu",
  "指定模型窗口": "Spécifier la fenêtre du modèle",
  "指定模型窗口需要填写正整数。": "Une fenêtre de modèle spécifiée doit être un entier positif.",
  "排队等待回答": "En attente de réponse",
  "服务端按当前模型窗口和完整请求预算计算历史目标；这里只保存比例与窗口偏好，不在浏览器中估算。": "Le serveur calcule l’objectif d’historique à partir de la fenêtre du modèle et du budget complet de la requête. Ce formulaire ne conserve que les préférences de ratio et de fenêtre ; le navigateur ne les estime pas.",
  "模型窗口": "Fenêtre du modèle",
  "窗口大小（tokens）": "Taille de la fenêtre (tokens)",
  "缺少可信能力信息时使用保守窗口。历史目标是比例与请求预算的较小值，由服务端在每次请求时计算。": "Une fenêtre prudente est utilisée lorsque les capacités fiables manquent. L’objectif d’historique est le plus petit du ratio et du budget de requête, calculé par le serveur à chaque requête.",
  "设置尚未读取完成，请稍后重试。": "Les paramètres ne sont pas encore chargés. Réessayez dans un instant.",
  "记忆浏览": "Parcourir les souvenirs",
  "本页 {0} 条承诺": "{0} engagements sur cette page",
  "本页关联 {0} 个事项": "{0} sujets de suivi associés sur cette page",
  "按已关联的记忆身份浏览；同名人物分别保留。": "Parcourez les identités liées aux souvenirs. Les homonymes restent distincts.",
  "本页暂无已关联的人物。可继续浏览记忆或主题。": "Aucune personne liée sur cette page. Vous pouvez parcourir les souvenirs ou les thèmes.",
