  "连接能带来什么": "Ce que la connexion apporte",
  "连接成功后，Mote 可以先从你选的一小部分资料开始认识你。": "Après la connexion, Mote peut commencer à vous connaître à partir d'un petit ensemble de documents choisis.",
  "把文件和记录变成可查的资料库": "Transformer fichiers et notes en bibliothèque consultable",
  "记住人物、事项和承诺，回答时引用原文": "Retenir personnes, sujets et engagements, et citer les originaux dans les réponses",
  "发现最近在忙什么，并给出下一步": "Voir vos activités récentes et proposer une prochaine étape",
  "新资料到达后更新相关事项，而不是只多一个文件": "Mettre à jour les sujets concernés à l'arrivée de nouveaux documents, pas seulement ajouter un fichier",
  "连接成功只表示可以同步，不代表全库已经理解。": "Une connexion réussie signifie seulement que la synchronisation est disponible ; elle ne signifie pas que toute la bibliothèque est comprise.",
  "这里只决定本次初次认识读取哪些已同步资料，不改变来源授权或保存方式。": "Ce choix détermine seulement les documents synchronisés lus lors de cette première découverte ; il ne modifie ni l'autorisation ni la conservation de la source.",
  "同步、正文提取和语义理解分别计算；连接或提取完成不等于语义理解完成。": "Synchronisation, extraction du texte et compréhension sémantique sont comptées séparément ; une connexion ou une extraction terminée ne signifie pas que la compréhension sémantique est terminée.",
  "初次认识暂不可用，仍可继续使用已同步的资料。": "La première découverte est indisponible ; les documents synchronisés restent utilisables.",
  "一次最多选择 100 份资料。": "Sélectionnez au plus 100 documents à la fois.",
  "本次仅处理已选的 {0} 份资料。": "Seuls les {0} documents sélectionnés sont traités cette fois.",
  "有新资料到达，可选择后再次开始初次认识。": "De nouveaux documents sont arrivés ; sélectionnez-les et relancez la première découverte.",
  "仅保存引用，未导入正文": "Référence seule ; le texte n'a pas été importé",
