  "原文提取未完成，请查看来源与处理状态。": "L'extraction du texte original n'est pas terminée ; vérifiez la source et l'état du traitement.",
  "理解没有完成，请检查模型与服务后重试。": "La compréhension n'est pas terminée ; vérifiez le modèle et les services, puis réessayez.",
  "这次选择的资料超过单次处理上限，请减少选择后重试。": "Les documents sélectionnés dépassent la limite d'un seul traitement ; réduisez la sélection et réessayez.",
  "取消后已完成的结果会保留；继续只会处理未完成的资料。": "L'annulation conserve les résultats terminés ; la reprise ne traite que les documents inachevés.",
  "本次选择的资料已完成；其他资料未包含。": "Les documents sélectionnés pour cette exécution sont terminés ; les autres ne sont pas inclus.",
  "本次资料": "Documents de cette exécution",
  "初次认识由你手动开始，仍会使用当前模型配置。": "La première découverte démarre uniquement à votre demande et utilise la configuration de modèle actuelle.",
  "初次认识仍只处理你选择的资料。": "La première découverte ne traite toujours que les documents que vous sélectionnez.",
  "保存方式沿用来源设置；需要更改时打开该来源的「连接与范围」。": "La conservation suit le réglage de chaque source ; ouvrez « Connexion et portée » de cette source pour la modifier.",
  "所选资料当前不可读取，请检查来源授权后重新选择。": "Les documents sélectionnés ne sont pas lisibles actuellement ; vérifiez l'autorisation de la source et sélectionnez à nouveau.",
