  "只处理你勾选的已同步资料；不会重新上传本机文件，也不会自动扩大来源范围。": "Seuls les documents synchronisés sélectionnés sont traités. Aucun fichier local n’est renvoyé et la portée des sources n’est jamais élargie automatiquement.",
