  "待处理的失败 {0} 项": "Échecs de lecture non résolus : {0}",
  "仍有分页待继续": "Il reste des pages à lire",
  "部分正文尚未读取": "Une partie du corps du contenu n’a pas encore été lue",
  "覆盖窗口": "Période couverte",
  "从 {0} 到 {1}": "De {0} à {1}",
  "截至 {0}": "Jusqu’au {0}",
  "首次同步建立基线，之后接入新增内容并跟踪已接入资料的修订。": "La première synchronisation établit une référence. Les suivantes recueillent le nouveau contenu et suivent les révisions des documents déjà collectés.",
  "可安全推进的解析会自动保存；关键缺口需要确认。": "Les résultats qui peuvent être enregistrés sans risque le sont automatiquement ; les lacunes importantes nécessitent une confirmation.",
  "解析未说明是否需要确认，请核对预览。": "L’analyse ne précise pas si une confirmation est nécessaire. Vérifiez l’aperçu.",
  "解析未说明继续处理的依据，请核对预览。": "L’analyse n’explique pas sur quelle base poursuivre. Vérifiez l’aperçu.",
  "飞书会话": "Conversations Feishu",
  "页面": "Page",
  "数据库": "Base de données",
  "频道": "Canal",
  "私信": "Message privé",
  "群组私信": "Message privé de groupe",
  "群聊": "Discussion de groupe",
  "此来源不在当前账号的已选范围中。请在连接设置中核对账号与范围。": "Cette source ne fait pas partie du périmètre sélectionné pour le compte actuel. Vérifiez le compte et le périmètre dans les paramètres de connexion.",
  "飞书会话需要单独的消息读取授权；不会开启发送权限。": "Les conversations Feishu nécessitent une autorisation distincte de lecture des messages. L’autorisation d’envoi n’est pas activée.",
  "在系统浏览器打开授权页面": "Ouvrir la page d’autorisation dans le navigateur système",
  "授权完成后返回此页并刷新状态。": "Après l’autorisation, revenez ici et actualisez l’état.",
  "授权未完成，请重试。": "L’autorisation n’est pas terminée. Réessayez.",
  "允许读取的内容": "Contenu dont la lecture est autorisée",
  "加载可选内容": "Charger le contenu disponible",
  "可选内容列表未完整返回，只能选择当前已列出的内容。": "La liste du contenu disponible est incomplète. Seuls les éléments actuellement affichés peuvent être sélectionnés.",
  "保存范围会启用所选来源的读取；未选内容不会接入，已有归档保留。": "L’enregistrement du périmètre active la lecture des sources sélectionnées. Le contenu non sélectionné n’est pas collecté et les archives existantes sont conservées.",
  "已选 {0} 项，最多可选 {1} 项。": "Sélection de {0} éléments sur un maximum de {1}.",
  "取消勾选一项后即可改选。": "Décochez un élément pour en sélectionner un autre.",
  "历史范围：{0}": "Périmètre de l’historique : {0}",
  "全部已授权历史": "Tout l’historique autorisé",
  "仅接入新增内容": "Nouveau contenu uniquement",
  "只读归档已选择的内容，按原始身份保留版本。": "Archivage en lecture seule du contenu sélectionné, avec conservation des versions sous leur identité d’origine.",
  "安装不等于授权。请先在插件中心完成配置和启用，再连接账号并选择读取范围。": "L’installation ne donne pas accès au contenu. Configurez et activez le plugin dans le centre des plugins, puis connectez le compte et choisissez le contenu à lire.",
  "停止飞书会话读取并暂停所选会话；已归档资料和飞书账号的其他连接保留。": "Arrêter la lecture des conversations Feishu et suspendre les discussions sélectionnées. Les archives et les autres connexions du compte Feishu sont conservées.",
  "删除这条原始记录及不再被引用的影像；仍有效的记忆保留，原文将无法回看或引用。": "Supprimer cet enregistrement original et les images qui ne sont plus référencées. Les souvenirs encore valides sont conservés ; l’original ne pourra plus être consulté ni cité.",
  "删除中央文件原件和解析正文；仍有效的记忆保留，原文将无法回看或引用。来源设备上的原文件保留。": "Supprimer le fichier original et le texte analysé dans Central. Les souvenirs encore valides sont conservés ; l’original ne pourra plus être consulté ni cité. Le fichier original sur l’appareil source est conservé.",
  "原件已释放，无法回看或引用；这条记忆仍可在其有效范围内使用。": "L’original a été libéré et ne peut plus être consulté ni cité. Ce souvenir reste utilisable dans son périmètre de validité.",
  "JSON 备份包含本机采集记录、上传状态和关联图片，恢复后保留上传状态。来源文件和会议录音需另行备份。": "Les sauvegardes JSON incluent les enregistrements capturés localement, leur état d’envoi et les images associées. La restauration conserve cet état. Les fichiers sources et les enregistrements de réunion doivent être sauvegardés séparément.",
  "清理本机副本": "Supprimer la copie locale",
  "本机副本已清理": "Copie locale supprimée",
  "仅清理已确认上传的本机副本；保留时间、来源和上传凭据，不影响中央归档或用户源文件。": "Supprimer uniquement une copie locale dont le téléversement a été confirmé. La date, la source et le reçu sont conservés ; les archives Central et vos fichiers source restent inchangés.",
  "本机原件不在此设备，连接原中央后可按当前权限读取。": "L’original n’est pas sur cet appareil. Connectez-vous au Central d’origine pour le lire avec vos autorisations actuelles.",
  "原中央与当前连接不一致，未发送读取请求。": "Le Central d’origine ne correspond pas à la connexion actuelle. Aucune demande de lecture n’a été envoyée.",
  "从中央另存原件": "Enregistrer l’original depuis Central",
  "采集阶段仍有待处理输入，暂不能清理本机副本。": "Des entrées restent en attente dans les étapes de capture. Cette copie locale ne peut pas encore être supprimée.",
  "本机副本清理尚未完成；请重试，尚存输入不会用于重新上传。": "La copie locale n’a pas été entièrement supprimée. Réessayez ; les entrées restantes ne seront pas téléversées à nouveau.",
  "采集范围与隐私": "Périmètre de collecte et confidentialité",
